WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, MIN(prev_txn_time) AS first_seen, SUM(is_new_burst) AS total_is_new_burst, GROUPING(CASE WHEN island_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM sessionized GROUP BY ROLLUP (CASE WHEN island_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY total_is_new_burst NULLS LAST
